//! Syscall name to number tables, one column per architecture.
//!
//! Generated by `tools/gen-syscall-tables.py`. Do not edit by
//! hand: regenerate instead, so that every architecture stays in
//! step with the same kernel release.
//!
//! `NAMES` is sorted, so a name resolves by binary search and then
//! indexes every per-architecture column at the same position. A
//! column entry of `ABSENT` means the architecture does not
//! implement that call, which a profile may legitimately name.

/// A syscall the architecture does not implement.
pub const ABSENT: i32 = -1;

/// Number of syscalls the tables cover.
pub const COUNT: usize = 486;

